	(120, 'widget_custom_html', 'a:5:{i:2;a:2:{s:5:"title";s:0:"";s:7:"content";s:617:"<div class="footer-wrapper one">\r\n   <div class="logo aos-init aos-animate" data-aos="fade-up" data-aos-delay="200"><img src="http://ai.test/wp-content/uploads/2025/11/logo-white.png" alt=""></div>\r\n   <div class="des pt-20 aos-init aos-animate" data-aos="fade-up" data-aos-delay="300">\r\n      <p class="pr-20 text-justify">Artificial intelligence is intelligence demonstrated by machines, as opposed to intelligence of humans and other animals. Example tasks in which this is done include speech recognition, computer vision, translation between languages, as well as other mappings of inputs.</p>\r\n   </div>\r\n</div>";}i:3;a:2:{s:5:"title";s:10:"Contact Us";s:7:"content";s:225:"<div data-aos="fade-up" data-aos-delay="300" class="aos-init aos-animate">\r\n   <span>3487 Harter StreetDayton, OH 45402</span>\r\n   <span>info@demo.com</span>\r\n	<br/>\r\n   <strong class="phone">+ (008)-345-6789</strong>\r\n</div>";}i:5;a:2:{s:5:"title";s:10:"Quick Link";s:7:"content";s:665:"<div class="footer-wrapper two custom_link mt-4 mt-md-0">\r\n   <ul data-aos="fade-up" data-aos-delay="300" class="aos-init aos-animate">\r\n      <li><a href="/react_facontech/index-2">About Us</a></li>\r\n      <li><a href="/react_facontech/index-2">Services</a></li>\r\n      <li><a href="/react_facontech/index-2">Blog</a></li>\r\n      <li><a href="/react_facontech/index-2">Pricing Plan</a></li>\r\n      <li><a href="/react_facontech/index-2">Our Team</a></li>\r\n      <li><a href="/react_facontech/index-2">All Projects</a></li>\r\n      <li><a href="/react_facontech/index-2">Contact</a></li>\r\n      <li><a href="/react_facontech/index-2">Trams</a></li>\r\n   </ul>\r\n</div>";}i:6;a:2:{s:5:"title";s:0:"";s:7:"content";s:617:"<div class="footer-wrapper one">\r\n   <div class="logo aos-init aos-animate" data-aos="fade-up" data-aos-delay="200"><img src="http://ai.test/wp-content/uploads/2025/11/logo-white.png" alt=""></div>\r\n   <div class="des pt-20 aos-init aos-animate" data-aos="fade-up" data-aos-delay="300">\r\n      <p class="pr-20 text-justify">Artificial intelligence is intelligence demonstrated by machines, as opposed to intelligence of humans and other animals. Example tasks in which this is done include speech recognition, computer vision, translation between languages, as well as other mappings of inputs.</p>\r\n   </div>\r\n</div>";}s:12:"_multiwidget";i:1;}', 'yes'),
